export default{cssContent:"/*\n * Copyright 2016 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.dt-range-input {\n  appearance: none;\n  margin: 0;\n  padding: 0;\n  height: 10px;\n  width: 88px;\n  outline: none;\n  background: none;\n}\n\n.dt-range-input::-webkit-slider-thumb,\n.-theme-preserve {\n  appearance: none;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  width: 12px;\n  height: 12px;\n  margin-top: -5px;\n  border-radius: 50%;\n  background-color: var(--color-primary-old);\n}\n\n.dt-range-input::-webkit-slider-runnable-track {\n  appearance: none;\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  height: 2px;\n  background-color: var(--color-background-elevation-2);\n}\n\n.dt-range-input:focus::-webkit-slider-thumb {\n  box-shadow: 0 0 0 2px var(--color-primary-variant);\n}\n\n.dt-range-input:disabled::-webkit-slider-thumb {\n  background-color: var(--color-text-disabled);\n}\n\n@media (forced-colors: active) {\n  .dt-range-input {\n    forced-color-adjust: none;\n  }\n}\n"};